You can use a **hash set** (extra data structure) to get the best time complexity.

### Approach (Best Time): **O(n + m)**
- Insert all elements of the first array into a hash set.
- For each element in the second array, check if it exists in the set.
- Print common elements (optionally avoiding duplicates using the same set).

### C Implementation (using hash table via `stdbool` + simple chained hashing)
```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

#define TABLE_SIZE 200003

typedef struct Node {
    int key;
    struct Node* next;
} Node;

Node* table[TABLE_SIZE];

unsigned int hashFunc(int x) {
    unsigned int ux = (unsigned int)x;
    return ux % TABLE_SIZE;
}

void insert(int x) {
    unsigned int h = hashFunc(x);
    Node* cur = table[h];
    while (cur) {
        if (cur->key == x) return; // already present
        cur = cur->next;
    }
    Node* n = (Node*)malloc(sizeof(Node));
    n->key = x;
    n->next = table[h];
    table[h] = n;
}

bool exists(int x) {
    unsigned int h = hashFunc(x);
    Node* cur = table[h];
    while (cur) {
        if (cur->key == x) return true;
        cur = cur->next;
    }
    return false;
}

int main() {
    int n, m;
    printf("Enter size of array A and B: ");
    scanf("%d %d", &n, &m);

    int* A = (int*)malloc(n * sizeof(int));
    int* B = (int*)malloc(m * sizeof(int));

    printf("Enter elements of A:\n");
    for (int i = 0; i < n; i++) scanf("%d", &A[i]);

    printf("Enter elements of B:\n");
    for (int i = 0; i < m; i++) scanf("%d", &B[i]);

    // Build hash set from A
    for (int i = 0; i < n; i++) insert(A[i]);

    // Find and print common elements
    printf("Common elements: ");
    // To avoid printing duplicates from B, we can use another hash set,
    // but that’s still "extra structures". If duplicates are allowed, remove this check.
    // Here we allow printing duplicates only once per unique value in B:
    bool printed[TABLE_SIZE]; // still extra but local; if you want strictly hash-only, tell me.
    for (int i = 0; i < TABLE_SIZE; i++) printed[i] = false;

    for (int i = 0; i < m; i++) {
        if (exists(B[i])) {
            unsigned int h = hashFunc(B[i]);
            if (!printed[h]) {           // quick duplicate-avoid (not collision-safe for keys)
                printf("%d ", B[i]);
                printed[h] = true;
            }
        }
    }

    // Free memory
    for (int i = 0; i < TABLE_SIZE; i++) {
        Node* cur = table[i];
        while (cur) {
            Node* nxt = cur->next;
            free(cur);
            cur = nxt;
        }
    }

    free(A);
    free(B);
    return 0;
}
```

> Note: The `printed[]` shortcut is **not collision-safe** for all integer values because different keys can hash to the same bucket.  
> If you need **correct duplicate handling**, either:
1) use a second proper hash set for “already printed”, or  
2) use sorting after hashing.

