// Compute the n-th term of the sequence:
// T(1)=0, T(2)=T(3)=-1, and for n>=4:
//    T(n) = T(n-1) + T(n-2) + T(n-3)
long long tribonacci(int n) {
    if (n <= 0) {
        // invalid
        return 0;
    }
    if (n == 1) return 0;
    if (n == 2 || n == 3) return -1;

    long long t1 = 0;   // T(1)
    long long t2 = -1;  // T(2)
    long long t3 = -1;  // T(3)
    long long tn = 0;

    for (int i = 4; i <= n; ++i) {
        tn = t1 + t2 + t3;
        // shift window
        t1 = t2;
        t2 = t3;
        t3 = tn;
    }
    return tn;
}

int main() {
    int n;
    cout << "Enter n (>= 1): ";
    cin >> n;

    if (!cin || n < 1) {
        cerr << "Error: please enter an integer >= 1.\n";
        return 1;
    }

    long long result = tribonacci(n);
    cout << "T(" << n << ") = " << result << "\n";
    return 0;
}
```

