Below is a simple C++ program that finds and prints all common elements between two integer arrays in O(n log n + m log m) time, without using any extra data structures beyond a handful of scalar variables.  It works by sorting each array in place and then doing a linear “two‐pointer” merge sweep to collect the intersections.

```cpp
#include <iostream>
#include <algorithm>
#include <vector>
using namespace std;

int main() {
    int n, m;
    // Read sizes of the two arrays
    cout << "Enter size of first array: ";
    cin >> n;
    cout << "Enter size of second array: ";
    cin >> m;

    vector<int> A(n), B(m);
    cout << "Enter " << n << " elements of first array:\n";
    for (int i = 0; i < n; ++i) {
        cin >> A[i];
    }

    cout << "Enter " << m << " elements of second array:\n";
    for (int j = 0; j < m; ++j) {
        cin >> B[j];
    }

    // Sort both arrays in place (no extra DS)
    sort(A.begin(), A.end());
    sort(B.begin(), B.end());

    // Two pointers to sweep through both sorted arrays
    int i = 0, j = 0;
    cout << "Common elements are:\n";
    while (i < n && j < m) {
        if (A[i] < B[j]) {
            ++i;
        }
        else if (A[i] > B[j]) {
            ++j;
        }
        else {
            // A[i] == B[j]
            cout << A[i] << " ";
            ++i;
            ++j;
        }
    }
    cout << "\n";

    return 0;
}
```

How it works:

1. We sort both input arrays in place.  
2. We maintain two indices, `i` for the first array and `j` for the second.  
3. At each step:
   - If `A[i] < B[j]`, we know `A[i]` cannot match anything further in `B`, so we advance `i`.
   - If `A[i] > B[j]`, we advance `j`.
   - If they are equal, we’ve found a common element; we print it and advance both `i` and `j`.  
4. No extra arrays, hash‐tables, or other data structures are used—only the two input arrays (sorted in place) and a few integer counters.

