Here’s an O(n + m)‐time, O(min(n,m))‐space solution using a hash table (unordered_map) to handle duplicates correctly.  We:

1. Read both arrays A (size n) and B (size m).  
2. Build a frequency map of the smaller array.  
3. Scan the larger array; whenever we see an element that still has positive count in the map, we output it and decrement the count.  

Because each element is inserted/looked‐up/decremented at most once, the running time is O(n+m) on average.

```cpp
#include <iostream>
#include <vector>
#include <unordered_map>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    vector<int> A(n), B(m);
    for(int i = 0; i < n; i++) {
        cin >> A[i];
    }
    for(int j = 0; j < m; j++) {
        cin >> B[j];
    }

    // We build the map on the smaller array to save a bit of space:
    vector<int> &small = (n <= m ? A : B);
    vector<int> &large = (n <= m ? B : A);

    unordered_map<int,int> freq;
    freq.reserve(small.size());
    for(int x : small) {
        ++freq[x];
    }

    cout << "Common elements are:\n";
    for(int x : large) {
        auto it = freq.find(x);
        if (it != freq.end() && it->second > 0) {
            cout << x << " ";
            --(it->second);          // consume one occurrence
        }
    }
    cout << "\n";
    return 0;
}
```

Explanation of complexity  
- Building the hash map on the smaller array: O(min(n,m)) average time.  
- Scanning the larger array and doing lookups/decrements: O(max(n,m)) average time.  
- Total expected time: O(n + m).  
- Extra space: O(min(n,m)) for the map.

